/* Practice MCQ bank — original questions written from /sections/deep-dives/ content.
   Study aids; not AICPA questions. Indexed tax dollar amounts are avoided or flagged.
   Fields: id, section, area, topic, stem, choices[4], answer (0-based index), explanation */
window.CPA_QUESTIONS = [

/* ============================== FAR ============================== */
{ id:"FARQ01", section:"FAR", area:"I", topic:"Cash flows (indirect)",
  stem:"Net income is $200,000. Depreciation expense is $30,000, accounts receivable increased $15,000, and accounts payable increased $10,000. Operating cash flow under the indirect method is:",
  choices:["$195,000","$225,000","$235,000","$255,000"], answer:1,
  explanation:"$200,000 + $30,000 (non-cash) − $15,000 (A/R up = cash down) + $10,000 (A/P up = cash up) = $225,000." },
{ id:"FARQ02", section:"FAR", area:"I", topic:"Cash flows (classification)",
  stem:"Equipment with a carrying amount of $40,000 is sold for $55,000 cash. In an indirect-method statement of cash flows, the transaction appears as:",
  choices:["$15,000 added in operating; $40,000 inflow in investing","$15,000 subtracted in operating; $55,000 inflow in investing","$55,000 added in operating only","$15,000 subtracted in operating; $40,000 inflow in financing"], answer:1,
  explanation:"The $15,000 gain is removed from operating (it isn't operating cash), and the FULL proceeds of $55,000 are an investing inflow. Never double-count the gain." },
{ id:"FARQ03", section:"FAR", area:"III", topic:"Leases (classification)",
  stem:"A lessee signs a 7-year lease of equipment with a remaining economic life of 8 years. Title does not transfer, there is no purchase option, the asset is not specialized, and PV of payments is 70% of fair value. The lessee classifies the lease as:",
  choices:["Operating, because PV is below substantially all of fair value","Finance, because the term is a major part of the remaining economic life","Operating, because title does not transfer","Short-term, because no purchase option exists"], answer:1,
  explanation:"Only ONE criterion is needed. 7 of 8 years (87.5%) is a major part (~75% threshold) of the remaining economic life → finance lease, even though the PV test (~90%) fails." },
{ id:"FARQ04", section:"FAR", area:"III", topic:"Leases (expense pattern)",
  stem:"For an operating lease, the lessee's income statement reports:",
  choices:["Amortization expense plus interest expense, producing front-loaded total expense","A single straight-line lease expense over the term","Interest expense only","Rent expense only when payments are made (cash basis)"], answer:1,
  explanation:"Operating leases produce a single, level straight-line lease expense. Finance leases produce amortization + interest (front-loaded). Both put an ROU asset and liability on the balance sheet." },
{ id:"FARQ05", section:"FAR", area:"III", topic:"Revenue (allocation)",
  stem:"Under ASC 606, when a contract contains multiple performance obligations, the transaction price is allocated based on:",
  choices:["Relative carrying amounts of the promised goods","The order in which obligations are satisfied","Relative standalone selling prices","Management's intended profit margin on each item"], answer:2,
  explanation:"Step 4 allocates the transaction price in proportion to standalone selling prices (observable, or estimated via adjusted market, cost-plus, or residual approaches)." },
{ id:"FARQ06", section:"FAR", area:"III", topic:"Revenue (variable consideration)",
  stem:"Variable consideration is included in the transaction price only to the extent that it is:",
  choices:["More likely than not to be received","Reasonably possible to be received","Highly probable that a significant revenue reversal will not occur","Certain, based on collection history"], answer:2,
  explanation:"The constraint: include variable amounts only to the extent it is highly probable a significant reversal in cumulative revenue will not occur when the uncertainty resolves." },
{ id:"FARQ07", section:"FAR", area:"III", topic:"Revenue (over time)",
  stem:"A contractor builds highly customized equipment with no alternative use and has an enforceable right to payment for performance completed to date. Revenue should be recognized:",
  choices:["At contract signing","When the customer takes physical possession","Over time, as performance progresses","Only when cash is collected"], answer:2,
  explanation:"No-alternative-use PLUS enforceable right to payment for work to date is one of the three over-time criteria — recognize using a measure of progress (input or output method)." },
{ id:"FARQ08", section:"FAR", area:"III", topic:"Income taxes (DTL)",
  stem:"A company uses MACRS for tax and straight-line for books, so tax depreciation exceeds book depreciation this year. The difference creates:",
  choices:["A deferred tax asset","A deferred tax liability","A permanent difference","A valuation allowance"], answer:1,
  explanation:"Taxable income is lower now and will be higher when the difference reverses → a deferred tax LIABILITY. Permanent differences never create deferred taxes." },
{ id:"FARQ09", section:"FAR", area:"III", topic:"Income taxes (valuation allowance)",
  stem:"A valuation allowance against a deferred tax asset is required when:",
  choices:["It is reasonably possible the DTA will not be realized","It is more likely than not that some or all of the DTA will not be realized","Any NOL carryforward exists","The company reports a book loss in the current year"], answer:1,
  explanation:"The standard is more-likely-than-not (>50%) non-realization, judged on all positive and negative evidence (future income, reversals, strategies). A current loss alone doesn't mandate one." },
{ id:"FARQ10", section:"FAR", area:"II", topic:"Receivables (CECL)",
  stem:"Under the CECL model (ASC 326), an entity recognizes credit losses on trade receivables:",
  choices:["Only when a loss is probable and estimable","When receivables are 90 days past due","As lifetime expected credit losses from initial recognition","Only upon write-off"], answer:2,
  explanation:"CECL is an expected-loss model: estimate lifetime expected credit losses at initial recognition using history, current conditions, and reasonable & supportable forecasts." },
{ id:"FARQ11", section:"FAR", area:"II", topic:"Bank reconciliation",
  stem:"In a bank reconciliation that adjusts both the bank and book balances to the true balance, deposits in transit are:",
  choices:["Added to the book balance","Subtracted from the bank balance","Added to the bank balance","Subtracted from the book balance"], answer:2,
  explanation:"Deposits in transit are recorded on the books but not yet by the bank → add to the BANK balance. Outstanding checks: subtract from bank. Bank fees/NSF: adjust the books." },
{ id:"FARQ12", section:"FAR", area:"II", topic:"Bonds (effective interest)",
  stem:"A bond issued at a discount is accounted for under the effective-interest method. Each period, interest expense equals:",
  choices:["Face amount × stated rate","Carrying amount × stated rate","Carrying amount × market (effective) rate at issuance","Face amount × market rate at each reporting date"], answer:2,
  explanation:"Expense = beginning carrying amount × historical effective rate. Cash = face × stated rate. The difference amortizes the discount, moving carrying value toward face." },
{ id:"FARQ13", section:"FAR", area:"II", topic:"Treasury stock",
  stem:"Under the cost method, a company reissues treasury stock for more than its repurchase cost. The excess is credited to:",
  choices:["Gain on sale of treasury stock (income)","Retained earnings","Additional paid-in capital from treasury stock transactions","Common stock"], answer:2,
  explanation:"Treasury-stock transactions never produce income-statement gains or losses. Excess over cost goes to APIC—Treasury Stock; deficiencies reduce that APIC, then retained earnings." },
{ id:"FARQ14", section:"FAR", area:"I", topic:"NFP reporting",
  stem:"A not-for-profit's statement of financial position reports net assets in which classes?",
  choices:["Unrestricted, temporarily restricted, and permanently restricted","With donor restrictions and without donor restrictions","Operating, investing, and financing","Board-designated and undesignated only"], answer:1,
  explanation:"Current guidance uses two classes: with donor restrictions and without donor restrictions. (The old three-class model was eliminated.) Board designations stay within 'without donor restrictions.'" },
{ id:"FARQ15", section:"FAR", area:"I", topic:"Governmental (modified accrual)",
  stem:"Under modified accrual, governmental funds recognize revenue when it is:",
  choices:["Earned, regardless of collection timing","Measurable and available","Collected in cash","Budgeted and appropriated"], answer:1,
  explanation:"Modified accrual recognizes revenue when measurable AND available (collectible within the period or soon enough to pay current-period liabilities). Full accrual (earned) applies to government-wide statements." },
{ id:"FARQ16", section:"FAR", area:"I", topic:"Governmental (reconciliation)",
  stem:"In reconciling total governmental fund balances to government-wide net position, capital assets used in governmental activities are:",
  choices:["Subtracted, because funds already report them","Added, because funds expensed them as capital outlay","Ignored, because they appear in proprietary funds","Reported only in the notes"], answer:1,
  explanation:"Governmental funds expense capital outlay (current financial resources focus). Government-wide statements capitalize and depreciate → ADD capital assets (net) in the reconciliation; long-term debt is subtracted." },
{ id:"FARQ17", section:"FAR", area:"III", topic:"Error correction",
  stem:"A company discovers that last year's depreciation was materially misstated due to a calculation error. The correction is reported as:",
  choices:["A change in estimate, prospectively","A change in principle, retrospectively","A prior-period adjustment restating the prior statements","A cumulative-effect adjustment in current income"], answer:2,
  explanation:"An ERROR is corrected by restatement — prior-period adjustment to beginning retained earnings and restating prior statements presented. Estimate changes are prospective; principle changes are retrospective." },
{ id:"FARQ18", section:"FAR", area:"III", topic:"Fair value hierarchy",
  stem:"A valuation uses quoted prices for SIMILAR assets in active markets and observable yield curves. This is:",
  choices:["Level 1","Level 2","Level 3","Not within the fair value hierarchy"], answer:1,
  explanation:"Level 2 = observable inputs other than quoted prices for identical items (similar assets, observable rates). Level 1 = identical assets in active markets; Level 3 = unobservable inputs." },
{ id:"FARQ19", section:"FAR", area:"III", topic:"Subsequent events",
  stem:"After year-end but before issuance, a major customer files for bankruptcy. The receivable existed at year-end and the customer's condition had been deteriorating all year. The company should:",
  choices:["Disclose only, because the bankruptcy occurred after year-end","Adjust the financial statements (recognized subsequent event)","Do nothing until cash collection fails","Reclassify the receivable as long-term"], answer:1,
  explanation:"The condition (customer's credit deterioration) existed at the balance-sheet date — a recognized (Type 1) subsequent event → adjust the allowance. A sudden post-year-end event (e.g., fire) would be disclosure-only." },
{ id:"FARQ20", section:"FAR", area:"I", topic:"OCI",
  stem:"Which item is reported in other comprehensive income?",
  choices:["Gain on sale of equipment","Foreign-currency translation adjustment","Treasury stock purchases","Dividends declared"], answer:1,
  explanation:"OCI includes translation adjustments, effective cash-flow-hedge gains/losses, AFS debt security unrealized G/L, and pension remeasurements. Equipment gains are net income; treasury stock and dividends are equity transactions." },

/* ============================== AUD ============================== */
{ id:"AUDQ01", section:"AUD", area:"IV", topic:"Opinions",
  stem:"The financial statements contain a material misstatement that is pervasive. The auditor should express:",
  choices:["A qualified opinion","An adverse opinion","A disclaimer of opinion","An unmodified opinion with an emphasis-of-matter paragraph"], answer:1,
  explanation:"Material + pervasive MISSTATEMENT → adverse. Pervasive SCOPE LIMITATION → disclaimer. Material but not pervasive (either cause) → qualified." },
{ id:"AUDQ02", section:"AUD", area:"IV", topic:"Opinions",
  stem:"The auditor is unable to obtain sufficient appropriate evidence, and the possible effects are material and pervasive. The auditor should:",
  choices:["Issue a qualified opinion","Issue an adverse opinion","Disclaim an opinion","Issue an unmodified opinion with an other-matter paragraph"], answer:2,
  explanation:"A pervasive scope limitation means the auditor cannot form an opinion → disclaimer. Adverse is for pervasive misstatements the auditor HAS evidence about." },
{ id:"AUDQ03", section:"AUD", area:"IV", topic:"Review engagements",
  stem:"In a SSARS review of a nonissuer, the accountant primarily performs:",
  choices:["Tests of controls and tests of details","Inquiry and analytical procedures","Confirmation of receivables and observation of inventory","Recalculation and reperformance"], answer:1,
  explanation:"A review = inquiry + analytical procedures, providing limited (negative) assurance. Audit-type corroborative procedures (confirmation, observation) are not required." },
{ id:"AUDQ04", section:"AUD", area:"I", topic:"Independence (compilation)",
  stem:"An accountant who is not independent may still perform which engagement for a nonissuer?",
  choices:["An audit, with expanded substantive testing","A review, with disclosure of the impairment","A compilation, disclosing the lack of independence in the report","An examination under the attestation standards"], answer:2,
  explanation:"Compilations (and preparations) don't require independence — but a compilation report must DISCLOSE the lack of independence. Audits, reviews, and examinations all require independence." },
{ id:"AUDQ05", section:"AUD", area:"I", topic:"Authority",
  stem:"The audit of a U.S. public company (issuer) is conducted under standards issued by:",
  choices:["The AICPA Auditing Standards Board","The PCAOB","The GAO","COSO"], answer:1,
  explanation:"Issuer audits follow PCAOB standards (with SEC independence rules). Nonissuers: AICPA SAS. Government audits: GAO Yellow Book. COSO is a control framework, not an audit standard-setter." },
{ id:"AUDQ06", section:"AUD", area:"III", topic:"Sampling (type)",
  stem:"An auditor wants to estimate the rate of deviation from a prescribed control procedure. The appropriate approach is:",
  choices:["Variables sampling","Attributes sampling","Probability-proportional-to-size sampling","Discovery of monetary misstatement"], answer:1,
  explanation:"Attributes sampling measures deviation RATES for tests of controls. Variables and MUS/PPS estimate dollar amounts for substantive testing." },
{ id:"AUDQ07", section:"AUD", area:"III", topic:"Sampling (size)",
  stem:"Which change causes a SMALLER sample size in a test of controls?",
  choices:["Increasing the tolerable deviation rate","Increasing the expected deviation rate","Decreasing the acceptable risk of overreliance","Increasing desired confidence"], answer:0,
  explanation:"A higher tolerable rate means more room for error → smaller sample. Higher expected deviations or higher confidence (lower acceptable risk) both push sample size UP." },
{ id:"AUDQ08", section:"AUD", area:"III", topic:"MUS/PPS",
  stem:"A key characteristic of monetary-unit (PPS) sampling is that it:",
  choices:["Treats each customer account as an equal sampling unit","Automatically emphasizes larger dollar items","Is most effective for detecting understatements","Cannot be used to project misstatement"], answer:1,
  explanation:"Each dollar is a sampling unit, so big-dollar items are more likely selected — efficient for overstatement testing; weak for understatements and zero/negative balances." },
{ id:"AUDQ09", section:"AUD", area:"III", topic:"Confirmations",
  stem:"Negative accounts-receivable confirmations are appropriate when:",
  choices:["The assessed risk of material misstatement is high","Balances are large and few","RMM is low, items are small and numerous, and recipients will give them attention","Management refuses positive confirmations"], answer:2,
  explanation:"Negative confirmations (reply only if you disagree) need: low RMM, many small homogeneous balances, low expected exceptions, and recipients likely to read them." },
{ id:"AUDQ10", section:"AUD", area:"III", topic:"Assertions",
  stem:"To test the EXISTENCE of recorded accounts receivable, the auditor should:",
  choices:["Trace shipping documents to the sales journal","Vouch recorded receivables to supporting documents and confirm with customers","Compare the aging to prior years","Trace cash receipts to the bank statement only"], answer:1,
  explanation:"Existence (overstatement concern) tests recorded items back to support — vouching and confirmation. Tracing source documents INTO the records tests completeness (understatement)." },
{ id:"AUDQ11", section:"AUD", area:"II", topic:"ITGC",
  stem:"Which is an IT GENERAL control rather than an application control?",
  choices:["An input edit check rejecting invalid dates","A three-way match within the purchasing module","Program change-management procedures requiring testing and approval before migration","An automated credit-limit check on sales orders"], answer:2,
  explanation:"ITGCs (access security, change management, operations) support ALL applications. Edit checks, matches, and limit checks inside a specific process are application controls." },
{ id:"AUDQ12", section:"AUD", area:"II", topic:"SOC 1 reliance",
  stem:"A user auditor plans to rely on controls at a client's payroll service organization. The most useful report is a:",
  choices:["SOC 1 Type 1","SOC 1 Type 2","SOC 2 Type 1","SOC 3"], answer:1,
  explanation:"Reliance requires evidence of OPERATING EFFECTIVENESS over the period → SOC 1 Type 2 (SOC 1 because the controls are relevant to financial reporting)." },
{ id:"AUDQ13", section:"AUD", area:"II", topic:"Deficiencies",
  stem:"A deficiency in internal control such that there is a reasonable possibility a material misstatement will not be prevented or detected timely is a:",
  choices:["Control deficiency","Significant deficiency","Material weakness","Reportable condition"], answer:2,
  explanation:"That's the material-weakness definition. A significant deficiency is less severe but merits the attention of those charged with governance." },
{ id:"AUDQ14", section:"AUD", area:"II", topic:"Fraud",
  stem:"Which fraud risk is presumed in every audit?",
  choices:["Misappropriation of petty cash","Improper revenue recognition","Vendor kickbacks","Payroll ghost employees"], answer:1,
  explanation:"Auditing standards presume fraud risks in revenue recognition and address management override of controls in every audit." },
{ id:"AUDQ15", section:"AUD", area:"III", topic:"Going concern",
  stem:"Substantial doubt about going concern exists, management's plans do not alleviate it, and disclosure is adequate. The auditor should issue:",
  choices:["A disclaimer of opinion","An adverse opinion","An unmodified opinion with a separate going-concern (emphasis) section","A qualified opinion"], answer:2,
  explanation:"Adequate disclosure → unmodified opinion plus a required separate section highlighting the substantial doubt. INADEQUATE disclosure would be a misstatement → qualified/adverse." },
{ id:"AUDQ16", section:"AUD", area:"III", topic:"Representations",
  stem:"The management representation letter should be dated as of:",
  choices:["The balance-sheet date","The date fieldwork began","The date of the auditor's report","The date the statements are filed"], answer:2,
  explanation:"Representations must cover everything through the report date, so the letter is dated the same date as the auditor's report." },
{ id:"AUDQ17", section:"AUD", area:"II", topic:"Risk model",
  stem:"As assessed risk of material misstatement increases, the auditor responds by:",
  choices:["Accepting higher detection risk and reducing substantive testing","Accepting lower detection risk and increasing the persuasiveness of substantive procedures","Increasing reliance on management inquiry","Raising overall materiality"], answer:1,
  explanation:"AR = RMM × DR. Holding audit risk low, higher RMM forces DETECTION risk down → more persuasive evidence: better nature, later timing, larger extent." },
{ id:"AUDQ18", section:"AUD", area:"III", topic:"Analytical procedures",
  stem:"Analytical procedures are REQUIRED during which phases of an audit?",
  choices:["Risk assessment and overall review (conclusion)","Substantive testing only","Internal control testing only","Engagement acceptance only"], answer:0,
  explanation:"Required at risk assessment (planning) and the final overall review. As substantive procedures they're optional — a choice of evidence." },
{ id:"AUDQ19", section:"AUD", area:"IV", topic:"CAMs",
  stem:"Critical audit matters (CAMs) are required in the audit report of:",
  choices:["All nonissuers","Issuers, under PCAOB standards","Governmental entities under the Yellow Book","Employee benefit plans only"], answer:1,
  explanation:"CAMs are a PCAOB (issuer) requirement. The AICPA's analogous Key Audit Matters are communicated for nonissuers only when the auditor is ENGAGED to report them." },
{ id:"AUDQ20", section:"AUD", area:"I", topic:"Engagement acceptance",
  stem:"Before accepting a new audit, the successor auditor should:",
  choices:["Obtain the predecessor's workpapers without client involvement","Communicate with the predecessor auditor after obtaining the client's permission","Issue the engagement letter, then assess independence","Begin substantive testing of opening balances"], answer:1,
  explanation:"The successor must attempt communication with the predecessor (disagreements, integrity, fee disputes, fraud) — but client permission is required first because of confidentiality." },

/* ============================== REG ============================== */
{ id:"REGQ01", section:"REG", area:"V", topic:"Partner basis",
  stem:"A partner contributes $50,000 cash to a new partnership. In year 1: share of ordinary income $20,000, share of partnership liabilities increases $10,000, cash distribution $15,000. Ending outside basis is:",
  choices:["$55,000","$65,000","$75,000","$45,000"], answer:1,
  explanation:"$50,000 + $20,000 income + $10,000 liability share − $15,000 distribution = $65,000. Partners include their share of partnership liabilities in basis." },
{ id:"REGQ02", section:"REG", area:"V", topic:"S corp loss limits",
  stem:"An S-corp shareholder has $10,000 stock basis and lent the corporation $5,000 directly. Her share of the current loss is $18,000. She may deduct (before at-risk/passive limits):",
  choices:["$18,000","$15,000","$10,000","$5,000"], answer:1,
  explanation:"Losses are limited to stock basis ($10,000) plus DEBT basis from direct loans ($5,000) = $15,000; the remaining $3,000 suspends until basis is restored. Entity-level bank debt gives NO basis." },
{ id:"REGQ03", section:"REG", area:"IV", topic:"Loss limitation ordering",
  stem:"The correct order for applying loss limitations to a pass-through loss is:",
  choices:["Passive → at-risk → basis","Basis → at-risk → passive","At-risk → basis → passive","Passive → basis → at-risk"], answer:1,
  explanation:"Basis first (§704(d)/§1366(d)), then at-risk (§465), then passive (§469) — then the excess-business-loss limit (§461(l)). Each gate suspends what it blocks." },
{ id:"REGQ04", section:"REG", area:"V", topic:"C corp distributions",
  stem:"A C corporation with $30,000 of E&P distributes $50,000 cash to its sole shareholder, whose stock basis is $15,000. The shareholder reports:",
  choices:["$50,000 dividend","$30,000 dividend; $20,000 capital gain","$30,000 dividend; $15,000 return of capital; $5,000 capital gain","$35,000 dividend; $15,000 return of capital"], answer:2,
  explanation:"Dividend to the extent of E&P ($30,000) → return of capital reducing basis ($15,000) → capital gain for the excess ($5,000)." },
{ id:"REGQ05", section:"REG", area:"III", topic:"§1245 recapture",
  stem:"Equipment cost $100,000; $60,000 depreciation taken; sold for $90,000. The $50,000 gain is characterized as:",
  choices:["$50,000 §1231 gain (LTCG treatment)","$50,000 ordinary income under §1245","$60,000 ordinary income; $10,000 capital loss","$40,000 ordinary; $10,000 §1231 gain"], answer:1,
  explanation:"Adjusted basis $40,000 → gain $50,000. §1245 recaptures the LESSER of gain ($50k) or depreciation taken ($60k) as ordinary → the entire $50,000 is ordinary. Gain above total depreciation would have been §1231." },
{ id:"REGQ06", section:"REG", area:"III", topic:"§1031 exchanges",
  stem:"In a qualifying like-kind exchange of real property, realized gain is $40,000 and the taxpayer receives $10,000 cash boot. Recognized gain is:",
  choices:["$0","$10,000","$40,000","$30,000"], answer:1,
  explanation:"Recognized gain = LESSER of realized gain ($40,000) or boot received ($10,000) = $10,000. The rest defers via a carryover basis in the replacement property." },
{ id:"REGQ07", section:"REG", area:"III", topic:"Gift basis",
  stem:"Donor's basis in stock is $20,000; FMV at gift is $12,000. The donee later sells for $15,000. The donee recognizes:",
  choices:["$3,000 gain","$5,000 loss","No gain or loss","$3,000 loss"], answer:2,
  explanation:"Dual-basis rule: gain basis = $20,000 (no gain — sold below it); loss basis = $12,000 FMV (no loss — sold above it). Selling between the two bases → no gain or loss." },
{ id:"REGQ08", section:"REG", area:"III", topic:"Inherited property",
  stem:"Property inherited from a decedent generally takes a basis equal to ____ and a holding period that is ____.",
  choices:["Decedent's basis; carryover","FMV at date of death (or alternate date); automatically long-term","Decedent's basis; automatically short-term","FMV at date of death; based on decedent's actual holding"], answer:1,
  explanation:"Inherited property gets a stepped-up (or down) basis to date-of-death FMV (or alternate valuation date) and is deemed LONG-term regardless of actual holding." },
{ id:"REGQ09", section:"REG", area:"I", topic:"Circular 230",
  stem:"Circular 230 governs:",
  choices:["GAAP departures on audited statements","Practice before the IRS by CPAs, attorneys, and enrolled agents","State board CPE requirements","PCAOB inspections of audit firms"], answer:1,
  explanation:"Circular 230 is the Treasury regulation governing practice before the IRS — duties, due diligence, fees, advertising, and sanctions (censure, suspension, disbarment, monetary penalties)." },
{ id:"REGQ10", section:"REG", area:"I", topic:"Preparer standards",
  stem:"To avoid a preparer penalty on an UNDISCLOSED, non-tax-shelter return position, the position generally needs:",
  choices:["A reasonable basis (~20%)","Substantial authority (~40%)","More-likely-than-not (>50%)","Any non-frivolous argument"], answer:1,
  explanation:"Undisclosed positions need SUBSTANTIAL AUTHORITY. With Form 8275 disclosure, reasonable basis suffices. Tax shelters/reportable transactions require more-likely-than-not." },
{ id:"REGQ11", section:"REG", area:"I", topic:"Tax procedure",
  stem:"Which court hears a tax dispute WITHOUT requiring the taxpayer to pay the deficiency first?",
  choices:["U.S. District Court","U.S. Court of Federal Claims","U.S. Tax Court","Small-claims division of state court"], answer:2,
  explanation:"Petition the Tax Court within 90 days of the statutory notice of deficiency — no prepayment. District Court and the Court of Federal Claims are refund forums (pay first, sue for refund)." },
{ id:"REGQ12", section:"REG", area:"II", topic:"Statute of Frauds",
  stem:"Which contract must be evidenced by a writing to be enforceable?",
  choices:["A 6-month service contract for $40,000","A sale of goods for $400","An oral agreement to sell land","Employment terminable at will"], answer:2,
  explanation:"MYLEGS: Marriage, >1 Year, LAND, Executor, Goods ≥ $500, Suretyship. Land contracts always require a writing; a 6-month service deal can be performed within a year; $400 goods is under the UCC threshold." },
{ id:"REGQ13", section:"REG", area:"II", topic:"Secured transactions",
  stem:"To obtain PMSI super-priority in a debtor's INVENTORY, the secured party must:",
  choices:["File within 20 days after the debtor receives the goods","Perfect before the debtor receives the inventory AND notify prior secured parties","Merely attach; perfection is automatic","Take possession of the inventory"], answer:1,
  explanation:"Inventory PMSI: perfect BEFORE delivery and give advance notice to earlier filers. The 20-day grace rule applies to PMSIs in equipment/non-inventory collateral." },
{ id:"REGQ14", section:"REG", area:"II", topic:"Suretyship",
  stem:"After paying the creditor in full, a surety steps into the creditor's rights against the debtor. This right is:",
  choices:["Exoneration","Contribution","Subrogation","Reimbursement from co-sureties"], answer:2,
  explanation:"Subrogation = stepping into the creditor's shoes (including collateral rights). Reimbursement runs against the debtor; contribution against co-sureties; exoneration compels the debtor to pay before the surety does." },
{ id:"REGQ15", section:"REG", area:"II", topic:"Bankruptcy",
  stem:"An individual with regular income who wants to keep assets and repay creditors over 3–5 years under a court-approved plan files under:",
  choices:["Chapter 7","Chapter 11","Chapter 13","Chapter 15"], answer:2,
  explanation:"Chapter 13 = individual wage-earner repayment plan. Chapter 7 = liquidation; Chapter 11 = reorganization (typically business); Chapter 15 = cross-border." },
{ id:"REGQ16", section:"REG", area:"V", topic:"Separately stated items",
  stem:"Which partnership item must be SEPARATELY STATED rather than included in ordinary business income?",
  choices:["Depreciation on equipment","Employee salaries","Charitable contributions","Rent expense on the warehouse"], answer:2,
  explanation:"Items that affect partners differently keep their character: charitable contributions, capital gains/losses, §1231, §179, investment income, foreign taxes. Operating items net into ordinary income." },
{ id:"REGQ17", section:"REG", area:"V", topic:"Schedule M-1",
  stem:"Book income includes $5,000 of municipal bond interest and $21,000 of federal income tax expense. Going from book to taxable income, you:",
  choices:["Add both","Subtract both","Subtract muni interest; add back federal tax expense","Add muni interest; subtract federal tax expense"], answer:2,
  explanation:"Muni interest is book income but never taxable → subtract. Federal income tax expense is a book expense but nondeductible → add back. Both are PERMANENT differences." },
{ id:"REGQ18", section:"REG", area:"IV", topic:"Estimated taxes",
  stem:"An individual whose prior-year AGI exceeded $150,000 avoids the underpayment penalty by paying at least:",
  choices:["100% of prior-year tax","110% of prior-year tax (or 90% of current-year tax)","90% of prior-year tax","125% of current-year tax"], answer:1,
  explanation:"Safe harbor = lesser of 90% of current-year tax or 110% of prior-year tax when prior AGI > $150,000 (100% otherwise)." },
{ id:"REGQ19", section:"REG", area:"III", topic:"Installment sales",
  stem:"Depreciable equipment with §1245 recapture potential is sold on an installment basis. The recapture amount is:",
  choices:["Recognized ratably as payments are received","Recognized in full in the year of sale","Deferred until the final payment","Eliminated by the installment election"], answer:1,
  explanation:"Depreciation recapture is recognized in FULL in the year of sale regardless of payments received; only the remaining gain spreads via the gross-profit ratio." },
{ id:"REGQ20", section:"REG", area:"II", topic:"Agency",
  stem:"A principal fires its purchasing agent but doesn't notify a long-time vendor, who accepts another order from the ex-agent. The principal is:",
  choices:["Not bound — actual authority ended","Bound under apparent authority","Bound only if the agent remits payment","Not bound because the contract is voidable"], answer:1,
  explanation:"Apparent authority survives termination until third parties receive notice (actual notice to known counterparties, constructive to others). The principal's failure to notify binds it." },

/* ============================== BAR ============================== */
{ id:"BARQ01", section:"BAR", area:"I", topic:"Liquidity ratios",
  stem:"Cash $50,000, net receivables $70,000, inventory $80,000, prepaid expenses $10,000, current liabilities $100,000. The quick ratio is:",
  choices:["2.10","1.20","1.30","0.83"], answer:1,
  explanation:"Quick = (cash + marketable securities + net A/R) / current liabilities = (50 + 70) / 100 = 1.20. Inventory and prepaids are excluded." },
{ id:"BARQ02", section:"BAR", area:"I", topic:"DuPont",
  stem:"Which is NOT a component of the three-factor DuPont decomposition of ROE?",
  choices:["Net profit margin","Total asset turnover","Equity multiplier","Dividend payout ratio"], answer:3,
  explanation:"ROE = margin × asset turnover × equity multiplier (leverage). Payout policy affects growth, not the ROE decomposition." },
{ id:"BARQ03", section:"BAR", area:"I", topic:"Breakeven",
  stem:"Fixed costs $120,000; selling price $50/unit; variable cost $30/unit. Breakeven volume is:",
  choices:["2,400 units","4,000 units","6,000 units","8,000 units"], answer:2,
  explanation:"CM/unit = $20 → 120,000 / 20 = 6,000 units (or $300,000 of sales at the 40% CM ratio)." },
{ id:"BARQ04", section:"BAR", area:"I", topic:"Materials variance",
  stem:"1,000 lbs purchased and used at $5.00/lb; standard price $4.50/lb. The materials price variance is:",
  choices:["$500 favorable","$500 unfavorable","$450 unfavorable","$50 favorable"], answer:1,
  explanation:"MPV = AQ × (AP − SP) = 1,000 × ($5.00 − $4.50) = $500 UNFAVORABLE (paid more than standard)." },
{ id:"BARQ05", section:"BAR", area:"I", topic:"Labor variance",
  stem:"Actual hours 2,100; standard hours allowed 2,000; standard rate $20. The labor efficiency variance is:",
  choices:["$2,000 unfavorable","$2,000 favorable","$2,100 unfavorable","$100 unfavorable"], answer:0,
  explanation:"LEV = SR × (AH − SH) = $20 × (2,100 − 2,000) = $2,000 UNFAVORABLE (used more hours than standard)." },
{ id:"BARQ06", section:"BAR", area:"I", topic:"Costing methods",
  stem:"Production exceeds sales this period. Compared with variable costing, absorption-costing operating income is:",
  choices:["Lower, because fixed overhead is expensed sooner","Higher, because fixed overhead is deferred in ending inventory","The same","Indeterminate without unit data"], answer:1,
  explanation:"Absorption capitalizes fixed OH into inventory; with rising inventory, part of fixed OH defers to future periods → higher current income than variable costing." },
{ id:"BARQ07", section:"BAR", area:"I", topic:"Capital budgeting",
  stem:"When NPV and IRR rank two mutually exclusive projects differently, the better decision rule is to:",
  choices:["Choose the higher IRR — it's a return measure","Choose the higher NPV — it measures value added at the cost of capital","Average the two rankings","Choose the shorter payback"], answer:1,
  explanation:"NPV assumes reinvestment at the cost of capital (realistic) and measures dollars of value created; IRR's reinvestment assumption and scale-insensitivity can mislead for mutually exclusive choices." },
{ id:"BARQ08", section:"BAR", area:"I", topic:"Payback",
  stem:"The payback method's primary weaknesses are that it ignores:",
  choices:["Project risk and inflation","The time value of money and cash flows after payback","Depreciation tax shields only","Initial investment size"], answer:1,
  explanation:"Payback measures time to recover the investment — without discounting, and blind to everything after recovery. Use NPV/PI for value decisions." },
{ id:"BARQ09", section:"BAR", area:"I", topic:"Cost estimation",
  stem:"Using the high-low method with $110,000 of cost at 10,000 units and $70,000 at 6,000 units, estimated fixed cost is:",
  choices:["$10,000","$40,000","$70,000","$4,000"], answer:0,
  explanation:"Variable = (110,000 − 70,000)/(10,000 − 6,000) = $10/unit. Fixed = 110,000 − (10 × 10,000) = $10,000." },
{ id:"BARQ10", section:"BAR", area:"II", topic:"Goodwill",
  stem:"Consideration transferred $800,000; fair value of NCI $200,000; fair value of identifiable net assets $900,000. Goodwill is:",
  choices:["$0","$100,000","$300,000","A bargain-purchase gain of $100,000"], answer:1,
  explanation:"Goodwill = (800 + 200) − 900 = $100,000. If the total had been BELOW fair value of net assets, the difference would be a bargain-purchase gain in income." },
{ id:"BARQ11", section:"BAR", area:"II", topic:"Intercompany profit",
  stem:"A 70%-owned subsidiary sells inventory to its parent at a profit; some remains in the parent's ending inventory. In consolidation, the unrealized profit elimination:",
  choices:["Is charged entirely to the controlling interest","Is allocated between the parent and the NCI","Is ignored if the sub is profitable","Increases consolidated revenue"], answer:1,
  explanation:"UPSTREAM (sub→parent) sales: the deferred profit is the SUB's, so the elimination is shared with the 30% NCI. Downstream eliminations hit only the parent." },
{ id:"BARQ12", section:"BAR", area:"II", topic:"Step acquisition",
  stem:"An investor holding 30% (equity method) buys another 40%, obtaining control. At the acquisition date the investor should:",
  choices:["Carry forward the 30% at its equity-method amount","Remeasure the previously held 30% to fair value and recognize the gain or loss in income","Record goodwill only on the new 40%","Defer any remeasurement to OCI"], answer:1,
  explanation:"A step acquisition remeasures the previously held interest to fair value at the control date with the gain/loss in earnings; acquisition accounting then applies to the whole business." },
{ id:"BARQ13", section:"BAR", area:"II", topic:"Hedge accounting",
  stem:"The effective portion of a gain on a derivative designated as a CASH FLOW hedge is reported in:",
  choices:["Net income immediately","OCI, reclassified to income when the hedged transaction affects earnings","Retained earnings directly","A deferred liability account"], answer:1,
  explanation:"Cash-flow-hedge effective portions park in OCI until the forecasted transaction hits earnings. Fair-value-hedge gains/losses go straight to income (offsetting the hedged item)." },
{ id:"BARQ14", section:"BAR", area:"II", topic:"Hedge types",
  stem:"A hedge of the foreign-currency exposure of a net investment in a foreign subsidiary reports the effective portion in:",
  choices:["Net income","OCI as part of the cumulative translation adjustment","Cost of goods sold","A contra-asset account"], answer:1,
  explanation:"Net-investment hedges follow the translation adjustment into OCI/CTA, offsetting the translation of the foreign operation." },
{ id:"BARQ15", section:"BAR", area:"III", topic:"Governmental reconciliation",
  stem:"Which item is ADDED when reconciling governmental fund balances to government-wide net position?",
  choices:["General obligation bonds payable","Capital assets, net of accumulated depreciation","Accrued interest payable","Compensated absences liability"], answer:1,
  explanation:"Funds expensed capital outlay, so capital assets are added back. Long-term liabilities (bonds, compensated absences) and accrued interest are SUBTRACTED — they're absent from fund statements." },
{ id:"BARQ16", section:"BAR", area:"III", topic:"Modified accrual",
  stem:"In governmental fund statements, the issuance of long-term bonds is reported as:",
  choices:["A liability on the fund balance sheet","An other financing source on the operating statement","Revenue","A direct addition to fund balance with no statement display"], answer:1,
  explanation:"Current-financial-resources focus: debt proceeds are an 'other financing source,' not a liability (the liability appears only government-wide). Capital outlay is an expenditure, not an asset." },
{ id:"BARQ17", section:"BAR", area:"I", topic:"Operating leverage",
  stem:"A firm with high operating leverage (large fixed costs) will experience:",
  choices:["Small profit changes from sales swings","Large profit changes from small sales swings","No breakeven point","Lower contribution margins by definition"], answer:1,
  explanation:"DOL = CM / operating income. Heavy fixed costs amplify the effect of volume changes on income — more upside in growth, more risk in decline." },
{ id:"BARQ18", section:"BAR", area:"I", topic:"Non-GAAP",
  stem:"When evaluating management's 'adjusted EBITDA,' the analyst's FIRST concern should be:",
  choices:["Whether it exceeds net income","The reconciliation to the nearest GAAP measure and consistency of adjustments period to period","Whether competitors disclose the same metric","Whether it is audited"], answer:1,
  explanation:"Non-GAAP measures are management-defined: verify the GAAP reconciliation, watch recurring 'one-time' addbacks, and check the definition doesn't shift opportunistically." },

/* ============================== ISC ============================== */
{ id:"ISCQ01", section:"ISC", area:"III", topic:"SOC reports",
  stem:"A service organization's controls relevant to user entities' financial reporting are covered by a:",
  choices:["SOC 1 report","SOC 2 report","SOC 3 report","SOC for Cybersecurity report"], answer:0,
  explanation:"SOC 1 addresses ICFR-relevant controls for user auditors. SOC 2/3 use the Trust Services Criteria; SOC for Cybersecurity covers the entity-wide cyber program." },
{ id:"ISCQ02", section:"ISC", area:"III", topic:"SOC reports",
  stem:"Which SOC report is designed for GENERAL (public) distribution?",
  choices:["SOC 1 Type 1","SOC 1 Type 2","SOC 2 Type 2","SOC 3"], answer:3,
  explanation:"SOC 3 is the general-use summary of a SOC 2 examination (often a website seal). SOC 1 and SOC 2 are restricted-use reports." },
{ id:"ISCQ03", section:"ISC", area:"III", topic:"Type 1 vs 2",
  stem:"A Type 2 SOC report differs from Type 1 in that it covers:",
  choices:["Design suitability only, at a point in time","Design AND operating effectiveness over a specified period","Only the subservice organizations","Only complementary user-entity controls"], answer:1,
  explanation:"Type 1 = design at a point in time. Type 2 = design + operating effectiveness over a period — what user auditors need for control reliance." },
{ id:"ISCQ04", section:"ISC", area:"III", topic:"CUECs",
  stem:"Complementary user-entity controls (CUECs) are controls that:",
  choices:["The service auditor performs during the examination","The subservice organization must design","The USER entity must implement for the service organization's controls to meet their objectives","The regulator imposes on the service organization"], answer:2,
  explanation:"CUECs are the user's responsibilities listed in the SOC report (e.g., approving its own users' access). User auditors must evaluate whether the user actually has them in place." },
{ id:"ISCQ05", section:"ISC", area:"III", topic:"Trust Services Criteria",
  stem:"Which Trust Services category is included in EVERY SOC 2 examination?",
  choices:["Availability","Privacy","Processing integrity","Security (the common criteria)"], answer:3,
  explanation:"Security is the mandatory baseline (common criteria); availability, processing integrity, confidentiality, and privacy are added per the engagement's scope." },
{ id:"ISCQ06", section:"ISC", area:"II", topic:"NIST CSF 2.0",
  stem:"The function ADDED in NIST Cybersecurity Framework 2.0 is:",
  choices:["Identify","Govern","Respond","Recover"], answer:1,
  explanation:"CSF 2.0's six functions: GOVERN (new), Identify, Protect, Detect, Respond, Recover. Govern covers strategy, roles, oversight, and supply-chain risk." },
{ id:"ISCQ07", section:"ISC", area:"II", topic:"Frameworks",
  stem:"The framework focused on the GOVERNANCE and management of enterprise IT (aligning IT with business objectives) is:",
  choices:["CIS Controls","COBIT","PCI-DSS","SOC 2"], answer:1,
  explanation:"COBIT (ISACA) is the IT governance/management framework. CIS = prescriptive technical safeguards; PCI-DSS = card-data requirements; SOC 2 = an examination, not a framework." },
{ id:"ISCQ08", section:"ISC", area:"II", topic:"IAM",
  stem:"Multi-factor authentication primarily strengthens:",
  choices:["Authorization","Authentication","Data classification","Change management"], answer:1,
  explanation:"MFA adds factors (know/have/are) to prove WHO you are — authentication. Authorization (what you may do) comes after identity is established." },
{ id:"ISCQ09", section:"ISC", area:"I", topic:"Segregation of duties",
  stem:"Which situation most directly violates IT segregation of duties?",
  choices:["A DBA reviewing performance logs","A developer migrating their own code into production","Help desk resetting passwords with identity verification","Operations running scheduled jobs"], answer:1,
  explanation:"Developers must not promote their own changes to production — change management requires independent testing/approval and a separate migrator. That's the classic ITGC finding." },
{ id:"ISCQ10", section:"ISC", area:"II", topic:"Cryptography",
  stem:"Hashing is BEST suited to provide:",
  choices:["Confidentiality of data in transit","Integrity verification of data or files","Availability of systems","Non-repudiation by itself"], answer:1,
  explanation:"A hash is a one-way fingerprint — compare hashes to detect alteration (integrity). Encryption provides confidentiality; signatures (hash + private key) add non-repudiation." },
{ id:"ISCQ11", section:"ISC", area:"II", topic:"Incident response",
  stem:"Immediately after IDENTIFYING an active ransomware incident, the next step is:",
  choices:["Eradication of the malware","Containment to stop the spread","Lessons-learned review","Public disclosure"], answer:1,
  explanation:"Lifecycle: prepare → identify → CONTAIN → eradicate → recover → lessons learned. Stop the bleeding (isolate systems) before cleanup and restore." },
{ id:"ISCQ12", section:"ISC", area:"I", topic:"Cloud models",
  stem:"Under an IaaS arrangement, the CUSTOMER is typically responsible for:",
  choices:["Physical data-center security","The hypervisor","The operating system, applications, and data","Nothing — the provider manages everything"], answer:2,
  explanation:"IaaS: provider supplies infrastructure up through virtualization; the customer manages OS and above. SaaS shifts almost everything but data/users/configuration to the provider. Security is always shared." },
{ id:"ISCQ13", section:"ISC", area:"II", topic:"GDPR",
  stem:"Under GDPR, a personal-data breach generally must be reported to the supervisory authority within:",
  choices:["24 hours","72 hours","30 days","One year"], answer:1,
  explanation:"72 hours of becoming aware (where feasible), with affected individuals notified without undue delay when risk is high. GDPR also reaches non-EU companies processing EU residents' data." },
{ id:"ISCQ14", section:"ISC", area:"II", topic:"Privacy regimes",
  stem:"PCI-DSS applies to organizations that:",
  choices:["Process protected health information","Store, process, or transmit payment-card data","Operate in the EU","Hold any personally identifiable information"], answer:1,
  explanation:"PCI-DSS is the card brands' contractual standard (12 requirements) for the cardholder-data environment. PHI → HIPAA; EU personal data → GDPR." },
{ id:"ISCQ15", section:"ISC", area:"I", topic:"Application security",
  stem:"The most direct mitigation for SQL injection is:",
  choices:["Stronger password policy","Parameterized queries / input validation","Full-disk encryption","Network segmentation"], answer:1,
  explanation:"SQL injection manipulates queries via untrusted input — neutralize it with parameterized queries, input validation/sanitization, and least-privilege database accounts." },
{ id:"ISCQ16", section:"ISC", area:"II", topic:"Resilience",
  stem:"Recovery Point Objective (RPO) measures:",
  choices:["Maximum tolerable downtime","Maximum tolerable DATA loss, expressed as time since the last recovery point","Time to detect an incident","The cost of an outage"], answer:1,
  explanation:"RPO = how much data you can afford to lose (drives backup frequency). RTO = how fast you must be back up (drives recovery capability/site strategy)." },
{ id:"ISCQ17", section:"ISC", area:"III", topic:"Subservice orgs",
  stem:"Under the CARVE-OUT method, a subservice organization's controls are:",
  choices:["Included in the description and tested","Excluded from the description, with relevant CSOCs identified","Always immaterial","Tested only by the user auditor"], answer:1,
  explanation:"Carve-out excludes the subservice org from the description/testing; the report identifies the complementary subservice-organization controls assumed. Inclusive brings them in-scope." },
{ id:"ISCQ18", section:"ISC", area:"I", topic:"Change management",
  stem:"A sound emergency-change process requires that emergency fixes be:",
  choices:["Exempt from documentation","Documented, reviewed, and approved after the fact","Made only by the original developer in production","Deferred to the next release regardless of impact"], answer:1,
  explanation:"Emergencies may move fast, but the control survives: retrospective documentation, independent review, and approval — otherwise the change-management ITGC fails." },

/* ============================== TCP ============================== */
{ id:"TCPQ01", section:"TCP", area:"II", topic:"S corp distributions",
  stem:"An S corporation with accumulated E&P from prior C-corp years makes a cash distribution exceeding its AAA. The excess over AAA is treated first as:",
  choices:["Return of capital","Capital gain","A taxable dividend from the C-corp E&P","Tax-exempt income"], answer:2,
  explanation:"Ordering: AAA (tax-free to basis) → DIVIDEND from old C-corp E&P → return of capital against remaining basis → capital gain." },
{ id:"TCPQ02", section:"TCP", area:"II", topic:"Debt basis",
  stem:"An S-corp shareholder's debt basis was reduced by pass-through losses. In a later profitable year, net increases first:",
  choices:["Increase stock basis","Restore debt basis up to its original amount","Create additional AAA only","Are distributed tax-free"], answer:1,
  explanation:"Net increases restore DEBT basis before stock basis. Repaying a shareholder loan while debt basis is reduced triggers gain to the shareholder." },
{ id:"TCPQ03", section:"TCP", area:"I", topic:"ISO taxation",
  stem:"An employee exercises an incentive stock option and HOLDS the shares. For that year she reports:",
  choices:["Ordinary income equal to the bargain element","No regular-tax income, but an AMT preference for the bargain element","Capital gain equal to the bargain element","Nothing for regular tax or AMT"], answer:1,
  explanation:"ISO exercise: no regular-tax event, but FMV − strike is an AMT adjustment — the classic AMT trap. NQSOs would be ordinary W-2 income at exercise." },
{ id:"TCPQ04", section:"TCP", area:"I", topic:"Disqualifying disposition",
  stem:"ISO shares are sold 8 months after exercise (18 months after grant). The bargain element is:",
  choices:["Long-term capital gain","Ordinary income in the year of sale","Tax-exempt","An AMT preference only"], answer:1,
  explanation:"Holding requirements (2 years from grant AND 1 year from exercise) failed → disqualifying disposition: bargain element becomes ordinary compensation income; the AMT adjustment reverses." },
{ id:"TCPQ05", section:"TCP", area:"I", topic:"RSUs",
  stem:"Restricted stock units are generally taxed to the employee:",
  choices:["At grant, on the grant-date value","At vesting, as ordinary income equal to FMV","Only when the shares are sold","At exercise, like options"], answer:1,
  explanation:"RSUs: ordinary income (W-2) at VESTING equal to FMV; basis = that FMV; later movement is capital gain/loss. There is no exercise and no §83(b) for standard RSUs." },
{ id:"TCPQ06", section:"TCP", area:"I", topic:"§83(b)",
  stem:"The main RISK of making a §83(b) election on restricted stock is:",
  choices:["It defers the start of the holding period","Tax paid at grant is not refundable if the stock is later forfeited","It converts capital gain into ordinary income","It is revocable at any time"], answer:1,
  explanation:"§83(b) accelerates tax to grant (usually a low value) and starts the capital-gains clock — but forfeit the shares and the tax paid is gone. The election (within 30 days) is essentially irrevocable." },
{ id:"TCPQ07", section:"TCP", area:"I", topic:"Charitable planning",
  stem:"For a client with highly appreciated long-term public stock and charitable intent, the best move is generally to:",
  choices:["Sell the stock and donate the after-tax cash","Donate the stock directly, deducting FMV and avoiding the gain","Donate only loss stock","Hold the stock and donate at death only"], answer:1,
  explanation:"Direct donation of LT appreciated stock: deduct FMV (30%-of-AGI limit) and never recognize the built-in gain. Loss stock: sell first to harvest the loss, then give cash." },
{ id:"TCPQ08", section:"TCP", area:"II", topic:"Trust DNI",
  stem:"Distributable net income (DNI) limits:",
  choices:["Only the trustee's fees","The trust's distribution deduction AND the amount taxable to beneficiaries","The trust's capital-gain rate","The number of beneficiaries"], answer:1,
  explanation:"DNI is the ceiling on both sides — the trust's deduction and the beneficiaries' income — and it carries CHARACTER (tax-exempt stays exempt) through to beneficiaries." },
{ id:"TCPQ09", section:"TCP", area:"II", topic:"Trust types",
  stem:"A trust that is REQUIRED to distribute all of its income currently and makes no corpus or charitable distributions is:",
  choices:["A complex trust","A grantor trust","A simple trust","A revocable living trust by definition"], answer:2,
  explanation:"That's the simple-trust definition (tested year by year). Accumulate income, distribute corpus, or give to charity → complex for that year." },
{ id:"TCPQ10", section:"TCP", area:"I", topic:"Gift splitting",
  stem:"Gift-splitting allows a married couple to:",
  choices:["Skip filing gift-tax returns entirely","Treat a gift made by one spouse as made one-half by each, doubling the annual exclusion per donee","Transfer unlimited amounts to grandchildren GST-free","Convert gifts into estate assets"], answer:1,
  explanation:"With both spouses' consent (gift-tax return required), one spouse's gift is split 50/50 — doubling annual-exclusion coverage per donee. GST has its own separate exemption." },
{ id:"TCPQ11", section:"TCP", area:"IV", topic:"Basis planning",
  stem:"For estate planning, a client should generally HOLD until death (rather than gift) assets that are:",
  choices:["Highly appreciated, to obtain the basis step-up","Declining in value, to preserve the loss","Generating losses currently","Cash and equivalents only"], answer:0,
  explanation:"Death steps basis to FMV — the built-in gain disappears for heirs. Gifts carry the donor's basis. Loss property should be SOLD by the owner (gifting wastes the loss via the dual-basis rule)." },
{ id:"TCPQ12", section:"TCP", area:"IV", topic:"§1033",
  stem:"A warehouse is destroyed by fire; insurance proceeds exceed basis. The owner can defer the gain by:",
  choices:["Electing the installment method","Reinvesting the proceeds in qualifying similar-use property within the replacement period","Donating the proceeds to charity","Carrying the gain back two years"], answer:1,
  explanation:"§1033 involuntary conversion: defer gain to the extent proceeds are reinvested in similar-use property within the replacement period (generally 2 years after the year gain is realized; 3 for condemned business realty)." },
{ id:"TCPQ13", section:"TCP", area:"III", topic:"Entity selection",
  stem:"A profitable consulting firm's owner wants to minimize self-employment/payroll taxes while taking cash out. The structure most associated with that goal is:",
  choices:["A general partnership","An S corporation paying reasonable wages plus distributions","A C corporation paying all earnings as salary","A sole proprietorship"], answer:1,
  explanation:"S-corp distributions avoid SE/payroll tax — AFTER reasonable W-2 compensation. Partnership/sole-prop active income is fully SE-taxed; all-salary C corp maximizes payroll tax." },
{ id:"TCPQ14", section:"TCP", area:"III", topic:"QSBS",
  stem:"To qualify for the §1202 QSBS exclusion, the stock must be issued by:",
  choices:["Any pass-through entity","A domestic C corporation meeting the gross-asset and active-business tests","An S corporation with one class of stock","A publicly traded partnership"], answer:1,
  explanation:"§1202 requires original-issue stock of a domestic C corporation (asset-size limit at issuance, active qualified business). Note: OBBBA created tiered 3/4/5-year exclusions for stock acquired after 7/4/2025 — testable from July 1, 2026." },
{ id:"TCPQ15", section:"TCP", area:"II", topic:"C corp NOLs",
  stem:"A C corporation's post-2017 net operating loss may be:",
  choices:["Carried back 2 years and forward 20","Carried forward indefinitely, limited to 80% of taxable income in the use year","Used without limitation in any year","Transferred to shareholders"], answer:1,
  explanation:"Post-2017 NOLs: no general carryback, indefinite carryforward, 80%-of-taxable-income limit. NOLs never pass through to C-corp shareholders." },
{ id:"TCPQ16", section:"TCP", area:"I", topic:"Passive losses",
  stem:"The cleanest way to free a client's suspended passive losses from a rental activity is to:",
  choices:["Convert the rental to personal use","Completely dispose of the activity in a taxable sale to an unrelated party","Gift the property to a child","Refinance the mortgage"], answer:1,
  explanation:"A complete taxable disposition to an unrelated party releases ALL suspended losses of that activity. Gifts don't release them (they fold into the donee's basis); conversions and refinancing change nothing." },
{ id:"TCPQ17", section:"TCP", area:"III", topic:"Liquidation",
  stem:"When a C corporation with appreciated assets liquidates, the result is generally:",
  choices:["A single tax at the shareholder level","A single tax at the corporate level","Tax at BOTH levels — corporate gain on the deemed asset sale and shareholder capital gain on the stock","No tax if assets are distributed in kind"], answer:2,
  explanation:"Liquidation = corporate-level gain as if assets sold at FMV, plus shareholder capital gain/loss (FMV − stock basis). In-kind distributions don't escape the corporate-level tax." },
{ id:"TCPQ18", section:"TCP", area:"II", topic:"UBTI",
  stem:"A tax-exempt organization is most likely to generate UBTI from:",
  choices:["Dividends on its endowment portfolio","Royalties from licensing its name","Operating a year-round commercial coffee shop unrelated to its mission","Rental income from unmortgaged real property"], answer:2,
  explanation:"UBTI = a regularly-carried-on trade or business not substantially related to the exempt purpose. Dividends, royalties, and most non-debt-financed real-property rents are excluded." }
];
